CREATE OR REPLACE FUNCTION public.fin_post_journal(_journal uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE j public.journal_entries; p public.accounting_periods; d numeric; c numeric; bad int;
BEGIN
  SELECT * INTO j FROM public.journal_entries WHERE id = _journal;
  IF j.id IS NULL THEN RAISE EXCEPTION 'Journal not found'; END IF;
  IF j.organization_id <> current_org_id() THEN RAISE EXCEPTION 'Not permitted'; END IF;
  IF NOT (public.neo_system_posting() OR has_permission('finance','approve') OR is_org_admin()) THEN
    RAISE EXCEPTION 'You do not have permission to post journals';
  END IF;
  IF j.status = 'posted' THEN RETURN jsonb_build_object('ok', true, 'already_posted', true, 'journal_id', j.id); END IF;
  IF j.status NOT IN ('draft','approved') THEN RAISE EXCEPTION 'Journal cannot be posted from status %', j.status; END IF;

  SELECT COALESCE(sum(debit),0), COALESCE(sum(credit),0) INTO d, c
    FROM public.journal_entry_lines WHERE journal_id = j.id;
  IF d = 0 AND c = 0 THEN RAISE EXCEPTION 'Journal has no lines'; END IF;
  IF d <> c THEN RAISE EXCEPTION 'Journal is not balanced (debit % vs credit %)', d, c; END IF;

  SELECT count(*) INTO bad FROM public.journal_entry_lines l
    JOIN public.chart_of_accounts a ON a.id = l.account_id
    WHERE l.journal_id = j.id AND (a.active = false OR a.postable = false OR a.is_header = true);
  IF bad > 0 THEN RAISE EXCEPTION 'Journal references inactive or non-postable accounts'; END IF;

  SELECT * INTO p FROM public.fin_period_for(j.organization_id, j.accounting_date);
  IF p.id IS NULL THEN RAISE EXCEPTION 'No accounting period covers %', j.accounting_date; END IF;
  IF p.status NOT IN ('open') AND NOT (p.status = 'soft_closed' AND j.journal_type = 'adjustment') THEN
    RAISE EXCEPTION 'Accounting period % is %', p.name, p.status;
  END IF;

  IF j.journal_type <> 'reversal' AND j.source_document_id IS NOT NULL AND EXISTS (
      SELECT 1 FROM public.journal_entries x
      WHERE x.organization_id = j.organization_id AND x.id <> j.id
        AND x.source_document_type = j.source_document_type
        AND x.source_document_id = j.source_document_id
        AND x.status = 'posted' AND x.journal_type <> 'reversal'
        AND x.reversed_by_journal_id IS NULL) THEN
    RAISE EXCEPTION 'This source document has already been posted';
  END IF;

  UPDATE public.journal_entries
    SET status='posted', total_debit=d, total_credit=c, period_id=p.id,
        posted_by=auth.uid(), posted_at=now()
    WHERE id = j.id;

  RETURN jsonb_build_object('ok', true, 'journal_id', j.id, 'total', d, 'period', p.name);
END $function$

CREATE OR REPLACE FUNCTION public.neo_assert_financial_account(_org uuid, _branch uuid, _account uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE b public.bank_accounts;
BEGIN
  IF _account IS NULL THEN RETURN NULL; END IF;
  SELECT * INTO b FROM public.bank_accounts WHERE id = _account AND organization_id = _org;
  IF b.id IS NULL THEN
    RAISE EXCEPTION 'That receiving account does not belong to this workspace';
  END IF;
  IF NOT coalesce(b.active, true) THEN
    RAISE EXCEPTION 'The receiving account % is no longer in use', b.name;
  END IF;
  IF b.branch_id IS NOT NULL AND _branch IS NOT NULL AND b.branch_id <> _branch THEN
    RAISE EXCEPTION 'The receiving account % belongs to another property', b.name;
  END IF;
  RETURN b.id;
END $function$

CREATE OR REPLACE FUNCTION public.neo_delivery_record_payment(_order uuid, _amount numeric, _method text DEFAULT 'cash'::text, _entry_type text DEFAULT 'payment'::text, _reference text DEFAULT NULL::text, _reason text DEFAULT NULL::text, _account uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  o public.delivery_orders;
  inv public.invoices;
  org uuid;
  v_method text := lower(nullif(btrim(coalesce(_method, '')), ''));
  v_entry text := lower(coalesce(nullif(btrim(_entry_type), ''), 'payment'));
  v_amount numeric := round(coalesce(_amount, 0)::numeric, 2);
  v_debit uuid; v_ar uuid; v_receipt text; v_payment uuid; v_journal uuid; v_jnum text;
  v_shift uuid;
  v_key text; v_balance numeric; acct uuid;
BEGIN
  IF v_entry NOT IN ('deposit','payment') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'bad_entry_type',
      'detail', 'Record either a deposit or a payment.');
  END IF;
  IF v_method IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'no_method',
      'detail', 'Choose how the money was received.');
  END IF;
  IF v_amount <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'bad_amount',
      'detail', 'The amount must be greater than zero.');
  END IF;

  SELECT * INTO o FROM public.delivery_orders WHERE id = _order FOR UPDATE;
  IF o.id IS NULL THEN RETURN jsonb_build_object('ok', false, 'reason', 'order_not_found'); END IF;
  org := o.organization_id;
  IF org <> public.current_org_id() THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'order_not_found');
  END IF;
  IF NOT public.neo_delivery_can_record_payment(org) THEN
    RAISE EXCEPTION 'Permission to record a payment is required.' USING ERRCODE = '42501';
  END IF;
  IF NOT public.neo_branch_in_scope(o.branch_id) THEN
    RAISE EXCEPTION 'That order is outside your access scope.' USING ERRCODE = '42501';
  END IF;

  acct := public.neo_assert_financial_account(org, o.branch_id, _account);

  SELECT * INTO inv FROM public.invoices
   WHERE organization_id = org AND notes LIKE '%delivery-order:' || _order::text || '%'
   ORDER BY created_at LIMIT 1
   FOR UPDATE;
  IF inv.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_billed',
      'detail', 'Raise the invoice for this delivery before recording money against it.');
  END IF;

  -- neo_delivery_payment_retry_v1
  v_key := 'delivery-payment:' || _order::text || ':' || v_entry || ':'
           || coalesce(nullif(btrim(coalesce(_reference,'')), ''), v_amount::text);

  SELECT id INTO v_payment FROM public.payments
   WHERE organization_id = org AND idempotency_key = v_key LIMIT 1;

  IF v_payment IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1
      FROM public.payments existing_payment
      WHERE existing_payment.id = v_payment
        AND existing_payment.organization_id = org
        AND existing_payment.source_record_id = _order
        AND existing_payment.amount = v_amount
        AND existing_payment.method = v_method
        AND existing_payment.destination_account_id
            IS NOT DISTINCT FROM acct
    ) THEN
      RETURN jsonb_build_object(
        'ok', false,
        'reason', 'idempotency_conflict',
        'detail', 'This reference already belongs to different payment details.'
      );
    END IF;

    RETURN jsonb_build_object('ok', true, 'already_recorded', true, 'payment_id', v_payment);
  END IF;

  v_balance := round(coalesce(inv.balance, 0)::numeric, 2);
  IF v_balance <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'nothing_outstanding',
      'detail', 'This delivery invoice is already settled.');
  END IF;
  IF v_amount > v_balance THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'amount_exceeds_balance',
      'detail', 'That is more than the outstanding balance on this delivery invoice.',
      'balance', v_balance);
  END IF;

  SELECT a.id INTO v_debit FROM public.chart_of_accounts a
   WHERE a.organization_id = org AND a.active AND coalesce(a.postable, true)
     AND a.code = public.neo_gl_account_code(org, v_method, acct)
   LIMIT 1;
  IF v_debit IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'no_settlement_account',
      'detail', 'No money account is configured for that payment method.');
  END IF;

  SELECT a.id INTO v_ar FROM public.chart_of_accounts a
   WHERE a.organization_id = org AND a.active AND coalesce(a.postable, true)
     AND a.name ILIKE 'Accounts Receivable'
   ORDER BY a.code LIMIT 1;
  IF v_ar IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'no_receivable_account',
      'detail', 'This property has no Accounts Receivable account.');
  END IF;


  -- neo_delivery_till_journal_v1
  v_shift := NULL;

  IF v_method = 'cash' THEN
    SELECT s.id INTO v_shift
    FROM public.pos_shifts s
    WHERE s.organization_id = org
      AND s.branch_id = o.branch_id
      AND s.cashier_id = auth.uid()
      AND s.status = 'open'
    ORDER BY s.opened_at DESC, s.id
    LIMIT 1
    FOR UPDATE;

    IF v_shift IS NULL THEN
      RAISE EXCEPTION
        'Open your cashier shift at this property before recording cash'
        USING ERRCODE = '23514';
    END IF;
  END IF;

  v_receipt := public.next_document_number('receipt', NULL, o.branch_id);

  INSERT INTO public.payments (organization_id, branch_id, receipt_number, customer_id, amount,
    currency, method, external_reference, status, received_by, notes, source_module,
    source_record_id, idempotency_key, destination_account_id, shift_id)
  VALUES (org, o.branch_id, v_receipt, o.customer_id, v_amount,
    coalesce(o.currency,'KES'), v_method, nullif(btrim(coalesce(_reference,'')), ''),
    'confirmed', auth.uid(),
    initcap(v_entry) || ' for delivery order ' || o.order_number || ' · invoice ' || inv.invoice_number
      || coalesce(' · ' || nullif(btrim(coalesce(_reason,'')), ''), ''),
    'delivery', _order, v_key, acct, v_shift)
  RETURNING id INTO v_payment;

  v_jnum := public.next_document_number('journal');
  INSERT INTO public.journal_entries (organization_id, branch_id, journal_number, journal_type,
    accounting_date, source_module, source_document_type, source_document_id, document_number,
    idempotency_key, description, currency, created_by, status)
  VALUES (org, o.branch_id, v_jnum, 'automatic', CURRENT_DATE, 'delivery', 'delivery_payment',
    v_payment, v_receipt, v_key,
    initcap(v_entry) || ' received on delivery order ' || o.order_number
      || ' against invoice ' || inv.invoice_number
      || coalesce(' — ' || nullif(btrim(coalesce(_reason,'')), ''), ''),
    coalesce(o.currency,'KES'), auth.uid(), 'draft')
  RETURNING id INTO v_journal;

  INSERT INTO public.journal_entry_lines (organization_id, journal_id, line_number, account_id,
    description, debit, credit, branch_id, customer_id, revenue_centre, payment_method)
  VALUES (org, v_journal, 1, v_debit, initcap(v_entry) || ' ' || v_receipt, v_amount, 0,
    o.branch_id, o.customer_id, 'delivery', v_method);

  INSERT INTO public.journal_entry_lines (organization_id, journal_id, line_number, account_id,
    description, debit, credit, branch_id, customer_id, revenue_centre, payment_method)
  VALUES (org, v_journal, 2, v_ar, 'Settlement of ' || inv.invoice_number, 0, v_amount,
    o.branch_id, o.customer_id, 'delivery', v_method);

  PERFORM public.fin_post_journal(v_journal);

  UPDATE public.payments SET posted_journal_id = v_journal, updated_at = now()
   WHERE id = v_payment;

  UPDATE public.invoices
     SET amount_paid = round(coalesce(amount_paid,0) + v_amount, 2),
         balance = round(coalesce(balance,0) - v_amount, 2),
         status = CASE WHEN round(coalesce(balance,0) - v_amount, 2) <= 0 THEN 'paid' ELSE status END,
         updated_at = now()
   WHERE id = inv.id
   RETURNING balance INTO v_balance;

  IF v_balance <= 0 THEN
    UPDATE public.delivery_orders
       SET payment_status = 'paid',
           payment_method = coalesce(payment_method, v_method),
           updated_at = now()
     WHERE id = _order;
  ELSIF v_entry = 'deposit' THEN
    UPDATE public.delivery_orders
       SET payment_status = 'partially-paid', updated_at = now()
     WHERE id = _order
       AND lower(coalesce(payment_status,'')) NOT IN ('paid','refunded');
  END IF;

  INSERT INTO public.audit_logs (organization_id, branch_id, user_id, user_name, action, module,
    record_id, previous_value, new_value, reason)
  VALUES (org, o.branch_id, auth.uid(),
    coalesce((SELECT full_name FROM public.profiles WHERE id = auth.uid()), ''),
    'delivery.payment.recorded', 'delivery', o.order_number,
    jsonb_build_object('invoice', inv.invoice_number, 'balance_before', inv.balance),
    jsonb_build_object('entry_type', v_entry, 'amount', v_amount, 'method', v_method,
      'receipt', v_receipt, 'journal', v_jnum, 'balance_after', v_balance,
      'destination_account_id', acct),
    nullif(btrim(coalesce(_reason,'')), ''));

  RETURN jsonb_build_object('ok', true, 'payment_id', v_payment, 'receipt_number', v_receipt,
    'journal_id', v_journal, 'journal_number', v_jnum, 'amount', v_amount,
    'entry_type', v_entry, 'invoice_number', inv.invoice_number, 'balance', v_balance,
    'destination_account_id', acct);
END;
$function$

CREATE OR REPLACE FUNCTION public.next_document_number(_doc_type text, _prefix text DEFAULT NULL::text, _branch uuid DEFAULT NULL::uuid, _org_override uuid DEFAULT NULL::uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _org uuid := coalesce(_org_override, public.current_org_id(), public.my_customer_org_id(),
                        (SELECT b.organization_id FROM public.branches b WHERE b.id = _branch));
  _year int := extract(year from now())::int;
  _pfx text := upper(coalesce(nullif(_prefix,''), left(regexp_replace(_doc_type,'[^A-Za-z]','','g'), 3)));
  _code text;
  _row public.number_sequences;
  _number text;
  _guard int := 0;
BEGIN
  IF _org IS NULL THEN
    RAISE EXCEPTION 'No active organization for the current user';
  END IF;

  -- neo_document_number_tenant_guard_v1
  IF COALESCE(auth.role(), '') <> 'service_role'
     AND (
       auth.uid() IS NOT NULL
       OR COALESCE(auth.role(), '') IN ('anon', 'authenticated')
     )
  THEN
    IF auth.uid() IS NULL
       OR NOT (
         COALESCE(_org = public.current_org_id(), false)
         OR EXISTS (
           SELECT 1
           FROM public.customers c
           WHERE c.organization_id = _org
             AND c.auth_user_id = auth.uid()
         )
       )
    THEN
      RAISE EXCEPTION
        'Not authorised to allocate document numbers for this organisation'
        USING ERRCODE = '42501';
    END IF;
  END IF;


  IF _branch IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.branches WHERE id = _branch AND organization_id = _org
  ) THEN
    RAISE EXCEPTION 'Property does not belong to the active organization';
  END IF;

  LOOP
    _guard := _guard + 1;
    IF _guard > 50 THEN
      RAISE EXCEPTION 'Unable to allocate a unique % reference', _doc_type;
    END IF;

    INSERT INTO public.number_sequences (organization_id, doc_type, branch_id, prefix, year, padding, next_number)
    VALUES (_org, _doc_type, _branch, _pfx, _year, 6, 1)
    ON CONFLICT (organization_id, doc_type, coalesce(branch_id, '00000000-0000-0000-0000-000000000000'::uuid))
    DO UPDATE SET
      next_number = CASE WHEN public.number_sequences.year = _year
                         THEN public.number_sequences.next_number + 1 ELSE 1 END,
      year = _year,
      updated_at = now()
    RETURNING * INTO _row;

    _code := NULL;
    IF _row.branch_id IS NOT NULL THEN
      SELECT upper(nullif(btrim(code), '')) INTO _code FROM public.branches WHERE id = _row.branch_id;
    END IF;

    _number := _row.prefix
      || CASE WHEN _code IS NULL THEN '' ELSE '-' || _code END
      || '-' || _row.year::text
      || '-' || lpad(_row.next_number::text, greatest(_row.padding, 4), '0');

    BEGIN
      INSERT INTO public.issued_document_numbers
        (organization_id, branch_id, doc_type, document_number, year, source, status, issued_by)
      VALUES (_org, _branch, _doc_type, _number, _year, 'generated', 'issued', auth.uid());
      RETURN _number;
    EXCEPTION WHEN unique_violation THEN
      CONTINUE;
    END;
  END LOOP;
END;
$function$
